cum={d:0 for d in top}
for lap in range(1,32):
 for d in top:
  x=by[nums[d]].get(lap)
  if x and x.get('lap_duration'):cum[d]+=x['lap_duration']
  else:cum[d]=None
 if lap in [1,2,3,5,8,10,15,20,25,28,29,30,31]:
  base=cum['RUS']
  print(lap,' '.join(f'{d}:{cum[d]-base:+.2f}' if cum[d] is not None else f'{d}:--' for d in top))
print('\nraw durations selected')
for lap in [1,2,3,4,5,10,15,20,25,28,29,30,31,35,36,38,39,40,45,49,50,51]:
 print('L',lap, ' '.join(f"{d}:{by[nums[d]].get(lap,{}).get('lap_duration','-')}" for d in top))
