import json,collections
D={x['driver_number']:x['name_acronym'] for x in json.load(open('/tmp/drivers.json'))}
laps=json.load(open('/tmp/laps.json')); by=collections.defaultdict(dict)
for x in laps:
 if x.get('lap_duration') is not None: by[x['driver_number']][x['lap_number']]=x['lap_duration']
cum={n:0 for n in D}
for lap in range(1,52):
